package ru.cherdakmd.chrdkguilds;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class GuildPeaceTest {
    @TempDir Path dir;
    final UUID leader=UUID.randomUUID(),member=UUID.randomUUID(),outsider=UUID.randomUUID();
    final long now=1_800_000_000_000L;
    GuildStore store(){return new GuildStore(dir,java.util.logging.Logger.getAnonymousLogger());}
    Guild guild(GuildStore s,long treasury) {
        Guild g=new Guild("guild","TestGuild","TAG",leader,now-1000);g.addMember(member,GuildRank.MEMBER);g.deposit(treasury);s.add(g);return g;
    }
    GuildPurse purse(long available) {return new GuildPurse(){public long take(UUID owner,long amount){return amount<=available?amount:0;}public long give(UUID owner,long amount){return 0;}};}
    Guild activate(GuildStore s,long treasury) {
        Guild g=guild(s,treasury);assertTrue(new GuildPeaceService(s).mode(purse(1000),leader,GuildMode.PEACEFUL,now).ok());return g;
    }
    @Test void oldClansStartBattleWithoutFees() {var s=store();var g=guild(s,50);assertFalse(g.peaceful());assertFalse(new GuildPeaceService(s).protects(member,now));assertFalse(new GuildPeaceService(s).daily(member,now,100).result().ok());assertEquals(50,g.treasury());}
    @Test void activationPaysWholeRosterWithTreasuryAndLeaderSupplement() {var s=store();var g=guild(s,15);var quote=new GuildFinance.Quote();assertTrue(new GuildPeaceService(s).mode(quote,leader,GuildMode.PEACEFUL,now).ok());assertEquals(5,quote.debit);assertEquals(0,g.treasury());assertEquals(2,g.peaceTerms().size());assertFalse(new GuildPeaceService(s).protects(member,now));assertTrue(new GuildPeaceService(s).protects(member,now+60_000));}
    @Test void insufficientFirstDayDoesNotEnableProtectionOrTakeTreasury() {var s=store();var g=guild(s,5);assertFalse(new GuildPeaceService(s).mode(purse(0),leader,GuildMode.PEACEFUL,now).ok());assertFalse(g.peaceful());assertEquals(5,g.treasury());}
    @Test void onlyLeaderChoosesModeOrPrepays() {var s=store();activate(s,100);assertEquals("not-leader",new GuildPeaceService(s).prepay(member,2,now).key());assertEquals("not-leader",new GuildPeaceService(s).mode(purse(100),member,GuildMode.BATTLE,now).key());}
    @Test void prepayCoversEveryCurrentMemberAndOnlyCollectiveMoney() {var s=store();var g=activate(s,100);long until=g.peaceTerm(member).paidUntil();assertTrue(new GuildPeaceService(s).prepay(leader,3,now).ok());assertEquals(until+3*GuildPeaceTerm.DAY,g.peaceTerm(member).paidUntil());assertEquals(20,g.treasury());assertEquals(g.peaceTerm(leader).paidUntil(),g.peaceTerm(member).paidUntil());}
    @Test void prepayDoesNotForgiveOverdueHours() {var s=store();var g=activate(s,100);long before=g.peaceTerm(member).paidUntil();assertTrue(new GuildPeaceService(s).prepay(leader,1,before+1000).ok());assertEquals(before+GuildPeaceTerm.DAY,g.peaceTerm(member).paidUntil());}
    @Test void invalidPrepayDoesNotMutateTreasury() {var s=store();var g=activate(s,100);long before=g.treasury();assertFalse(new GuildPeaceService(s).prepay(leader,0,now).ok());assertFalse(new GuildPeaceService(s).prepay(leader,31,now).ok());assertFalse(new GuildPeaceService(s).prepay(leader,30,now).ok());assertEquals(before,g.treasury());}
    @Test void ordinaryMemberPaysPersonallyNotFromTreasury() {var s=store();var g=activate(s,100);long due=g.peaceTerm(member).paidUntil(),treasury=g.treasury();var plan=new GuildPeaceService(s).daily(member,due,10);assertEquals(10,plan.debit());assertEquals(member,plan.payer());assertEquals(treasury,g.treasury());assertEquals(due+GuildPeaceTerm.DAY,g.peaceTerm(member).paidUntil());}
    @Test void leaderDailyUsesTreasuryThenPersonalBalance() {var s=store();var g=activate(s,25);long due=g.peaceTerm(leader).paidUntil();var plan=new GuildPeaceService(s).daily(leader,due,5);assertEquals(5,plan.debit());assertEquals(0,g.treasury());assertEquals(due+GuildPeaceTerm.DAY,g.peaceTerm(leader).paidUntil());}
    @Test void paidMemberIsNeverChargedTwiceForSamePeriod() {var s=store();var g=activate(s,100);long due=g.peaceTerm(member).paidUntil();assertTrue(new GuildPeaceService(s).daily(member,due,100).result().ok());assertFalse(new GuildPeaceService(s).daily(member,due+1,100).result().ok());}
    @Test void memberGetsExactlyOneAdditionalDayThenIsKicked() {var s=store();var g=activate(s,100);long due=g.peaceTerm(member).paidUntil();assertEquals("peace-member-grace",new GuildPeaceService(s).daily(member,due,0).result().key());assertTrue(new GuildPeaceService(s).protects(member,due+GuildPeaceTerm.DAY-1));assertFalse(new GuildPeaceService(s).daily(member,due+GuildPeaceTerm.DAY-1,0).result().ok());assertEquals("peace-auto-kick",new GuildPeaceService(s).daily(member,due+GuildPeaceTerm.DAY,0).result().key());assertNull(s.of(member));assertNotNull(s.of(leader));assertFalse(s.peaceNotices(member).isEmpty());}
    @Test void leaderGetsOneDayThenWholeClanDissolvesWithoutLeadershipTransfer() {var s=store();var g=activate(s,20);long due=g.peaceTerm(leader).paidUntil();assertEquals("peace-leader-grace",new GuildPeaceService(s).daily(leader,due,0).result().key());assertNotNull(s.of(leader));assertEquals("peace-auto-disband",new GuildPeaceService(s).daily(leader,due+GuildPeaceTerm.DAY,0).result().key());assertEquals(0,s.count());assertNull(s.of(member));assertFalse(s.peaceNotices(leader).isEmpty());assertFalse(s.peaceNotices(member).isEmpty());}
    @Test void unknownBankDoesNotStartGraceKickOrDissolve() {var s=store();var g=activate(s,20);long due=g.peaceTerm(leader).paidUntil();assertEquals("finance-paused",new GuildPeaceService(s).daily(leader,due+3*GuildPeaceTerm.DAY,-1).result().key());assertEquals(0,g.peaceTerm(leader).graceSince());assertNotNull(s.of(leader));}
    @Test void paymentDuringGraceKeepsMembershipAndRestoresFutureTerm() {var s=store();var g=activate(s,20);long due=g.peaceTerm(member).paidUntil();new GuildPeaceService(s).daily(member,due,0);assertTrue(new GuildPeaceService(s).daily(member,due+1000,10).result().ok());assertEquals(0,g.peaceTerm(member).graceSince());assertEquals(due+GuildPeaceTerm.DAY,g.peaceTerm(member).paidUntil());}
    @Test void restartKeepsTermsGraceAndRemainingDay() {var s=store();var g=activate(s,20);long due=g.peaceTerm(member).paidUntil();new GuildPeaceService(s).daily(member,due,0);s.saveNow();var loaded=store();loaded.load();assertEquals(g.peaceTerm(member),loaded.of(member).peaceTerm(member));assertFalse(new GuildPeaceService(loaded).daily(member,due+1000,0).result().ok());}
    @Test void disconnectedOfflinePeriodsAreCaughtUpWithoutFreeDays() {var s=store();var g=activate(s,20);long due=g.peaceTerm(member).paidUntil();var plan=new GuildPeaceService(s).daily(member,due+2*GuildPeaceTerm.DAY,100);assertEquals(30,plan.debit());assertEquals(due+3*GuildPeaceTerm.DAY,g.peaceTerm(member).paidUntil());}
    @Test void fineIsOncePerIncidentAndSurvivesClanRemovalAndRestart() {var s=store();var g=guild(s,100);var rules=new GuildPeaceService(s);assertTrue(rules.fine(member,now).ok());assertFalse(rules.fine(member,now+59_999).ok());assertEquals(100,s.sanction(member).debt());s.remove(g);s.saveNow();var loaded=store();loaded.load();assertEquals(100,loaded.sanction(member).debt());assertFalse(new GuildPeaceService(loaded).fine(member,now+1).ok());assertTrue(new GuildPeaceService(loaded).fine(member,now+60_000).ok());assertEquals(200,loaded.sanction(member).debt());}
    @Test void partialFineCollectionNeverRoundsOrForgivesDebt() {var s=store();var rules=new GuildPeaceService(s);rules.fine(outsider,now);var plan=rules.collect(outsider,37);assertEquals(37,plan.debit());assertTrue(plan.collectingDebt());assertEquals(63,s.sanction(outsider).debt());assertEquals(63,rules.collect(outsider,1000).debit());assertEquals(0,s.sanction(outsider).debt());assertFalse(rules.collect(outsider,100).result().ok());}
    @Test void finesDoNotRequireClanMembership() {var s=store();assertTrue(new GuildPeaceService(s).fine(outsider,now).ok());assertEquals(100,s.sanction(outsider).debt());}
    @Test void modeChangeCannotEraseDebtOrRefundPrepayment() {var s=store();var g=activate(s,100);long treasury=g.treasury();assertEquals("peace-mode-cooldown",new GuildPeaceService(s).mode(purse(100),leader,GuildMode.BATTLE,now+1).key());assertTrue(new GuildPeaceService(s).mode(purse(100),leader,GuildMode.BATTLE,now+GuildPeaceTerm.DAY).ok());assertEquals(treasury,g.treasury());assertTrue(g.peaceTerms().isEmpty());}
    @Test void indebtedMemberPreventsPeaceModeAndCombatPreventsSwitch() {var s=store();guild(s,100);new GuildPeaceService(s).fine(member,now);assertEquals("peace-debt-mode",new GuildPeaceService(s).mode(purse(100),leader,GuildMode.PEACEFUL,now).key());s.combatGuard(id->id.equals(leader));assertEquals("peace-combat",new GuildPeaceService(s).mode(purse(100),leader,GuildMode.PEACEFUL,now).key());}
    @Test void pendingWarCannotBeHiddenByPeaceMode() {var s=store();var g=guild(s,1000);var other=new Guild("other","OtherGuild","OTH",outsider,now);other.deposit(1000);s.add(other);s.addWar(new GuildWar("war",g.id(),other.id(),320,now));assertEquals("peace-war-busy",new GuildPeaceService(s).mode(purse(100),leader,GuildMode.PEACEFUL,now).key());}
    @Test void malformedTermsCannotSilentlyDropPaidProtection() {var s=store();activate(s,100);String json=s.snapshotJson();assertThrows(RuntimeException.class,()->s.detached(json.replace("PEACEFUL","UNKNOWN")));assertThrows(RuntimeException.class,()->s.detached(json.replace("\"paid-until\": ","\"paid-until\": -")));}
    @Test void combatWindowIsBoundedAndDoesNotDependOnOnlineStatus() {var combat=new GuildCombatTracker();combat.mark(member,now);assertTrue(combat.blocked(member,now+29_999));assertFalse(combat.blocked(member,now+30_000));combat.prune(now+30_000);assertFalse(combat.blocked(member,now+30_001));}
}
